def load_json(path):
    """Load and return parsed JSON from a file path."""
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def load_text(path):
    """Load and return text content from a file path."""
    with open(path, "r", encoding="utf-8") as f:
        return f.read()


def load_jsonl(path):
    """Load JSONL file and return a list of parsed objects."""
    events = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                events.append(json.loads(line))
    return events


@pytest.fixture(scope="module")
def pipeline_record():
    """Load the output pipeline record once per test module."""
    if not OUTPUT_PATH.exists():
        pytest.fail(f"Output file {OUTPUT_PATH} does not exist")
    return load_json(OUTPUT_PATH)


@pytest.fixture(scope="module")
def raw_output_text():
    """Load the raw output text for string-based checks."""
    if not OUTPUT_PATH.exists():
        pytest.fail(f"Output file {OUTPUT_PATH} does not exist")
    return load_text(OUTPUT_PATH)


class TestOutputExistenceAndFormat:
    """Tests for basic output file existence, parseability, and top-level shape."""

    def test_output_file_exists(self):
        """The pipeline_record.json must exist at the required path."""
        assert OUTPUT_PATH.exists(), f"{OUTPUT_PATH} does not exist"
        assert OUTPUT_PATH.is_file(), f"{OUTPUT_PATH} is not a file"

    def test_output_is_valid_json(self, pipeline_record):
        """Output must be parseable valid JSON."""
        assert pipeline_record is not None, "Output is None or not parseable"

    def test_top_level_is_object(self, pipeline_record):
        """Top-level value must be a JSON object."""
        assert isinstance(pipeline_record, dict), (
            f"Expected top-level object, got {type(pipeline_record).__name__}"
        )

    def test_required_top_level_keys_present(self, pipeline_record):
        """All 13 required top-level keys must be present."""
        missing = [k for k in REQUIRED_TOP_LEVEL_KEYS if k not in pipeline_record]
        assert not missing, f"Missing required top-level keys: {missing}"

    def test_no_extra_top_level_keys(self, pipeline_record):
        """No additional top-level keys beyond the required 13 are permitted."""
        actual_keys = list(pipeline_record.keys())
        extra = [k for k in actual_keys if k not in REQUIRED_TOP_LEVEL_KEYS]
        assert not extra, f"Extra top-level keys found: {extra}"

    def test_output_is_utf8(self, raw_output_text):
        """All string values must be UTF-8 encoded (file loaded successfully as UTF-8)."""
        try:
            raw_output_text.encode("utf-8")
        except UnicodeError as e:
            pytest.fail(f"Output contains non-UTF-8 content: {e}")


class TestNoEmbeddedBinaryOrPlaceholders:
    """Tests for negative constraints: no binary data, no placeholders, no external URLs."""

    def test_no_embedded_binary_data(self, pipeline_record):
        """JSON must not contain base64-encoded binary data or binary-looking strings."""
        raw_str = json.dumps(pipeline_record, ensure_ascii=False)
        # Check for common base64 padding patterns that indicate binary embedding
        # A simplistic check: long runs of base64-like characters with '==' padding
        import re
        base64_pattern = re.compile(r'[A-Za-z0-9+/]{100,}={0,2}')
        matches = base64_pattern.findall(raw_str)
        assert not matches, (
            f"Found potential base64-encoded binary data: {len(matches)} occurrences"
        )

    def test_no_placeholder_tokens(self, raw_output_text):
        """Output must not contain placeholder tokens like TODO, TBD, FIXME, etc."""
        placeholders = ["TODO", "TBD", "FIXME", "placeholder", "lorem ipsum", "sample text"]
        lower_text = raw_output_text.lower()
        found = [p for p in placeholders if p.lower() in lower_text]
        assert not found, f"Found placeholder tokens: {found}"

    def test_no_external_urls(self, raw_output_text):
        """Output must not contain http:// or https:// URLs."""
        assert "http://" not in raw_output_text, "Found forbidden http:// URL"
        assert "https://" not in raw_output_text, "Found forbidden https:// URL"


class TestContentPreservationAndStructure:
    """Tests that each pipeline stage field preserves source content with correct types."""

    def test_model_generation_preserves_content(self, pipeline_record):
        """model_generation must contain the original prompt and generated text."""
        source = load_json(INPUT_FILES["chat_completion_response.json"])
        output = pipeline_record["model_generation"]
        # The output should be an object (the source is an object)
        assert isinstance(output, dict), (
            f"model_generation should be an object, got {type(output).__name__}"
        )
        # Must contain at least the same top-level keys as the source
        for key in source:
            assert key in output, f"model_generation missing source key: {key}"

    def test_notebook_artifact_structure(self, pipeline_record):
        """notebook_artifact must embed notebook and enrichment metadata."""
        notebook_source = load_json(INPUT_FILES["formatted_notebook.ipynb"])
        enrichment_source = load_json(INPUT_FILES["notebook_enrichment_metadata.json"])
        output = pipeline_record["notebook_artifact"]
        assert isinstance(output, dict), (
            f"notebook_artifact should be an object, got {type(output).__name__}"
        )
        # Must contain 'notebook' sub-field
        assert "notebook" in output, "notebook_artifact missing 'notebook' sub-field"
        assert isinstance(output["notebook"], dict), "notebook sub-field should be an object"
        # Must contain 'enrichment_metadata' sub-field
        assert "enrichment_metadata" in output, (
            "notebook_artifact missing 'enrichment_metadata' sub-field"
        )
        assert isinstance(output["enrichment_metadata"], dict), (
            "enrichment_metadata sub-field should be an object"
        )
        # Notebook content should have cells key (standard ipynb structure)
        if "cells" in notebook_source:
            assert "cells" in output["notebook"], (
                "notebook sub-field missing 'cells' from source"
            )

    def test_social_media_post_preserves_card_mappings(self, pipeline_record):
        """social_media_post must contain post content and card mappings."""
        source = load_json(INPUT_FILES["xiaohongshu_post_payload.json"])
