    def test_cloud_scan_primary_has_lifecycle_events(self, pipeline_record):
        """cloud_scan_primary must capture task lifecycle events with timestamps and status codes."""
        source_text = load_text(INPUT_FILES["lianke_scan_primary.log"])
        output = pipeline_record["cloud_scan_primary"]
        # Output could be a string or a structured object; must be non-empty
        assert output, "cloud_scan_primary is empty"
        # If it's a string, it should contain key content from the log
        if isinstance(output, str):
            # At minimum, the output should contain some timestamp-like patterns
            assert len(output) > 0, "cloud_scan_primary string is empty"
            # Source log has multiple lines; output should not be a single empty line
            assert len(output.strip().split("\n")) >= 1, (
                "cloud_scan_primary should contain log content"
            )
        elif isinstance(output, dict):
            # Structured output should have events or raw_log
            has_events = "events" in output or "raw_log" in output
            assert has_events, (
                "cloud_scan_primary object missing 'events' or 'raw_log'"
            )

    def test_cloud_scan_redundant_has_lifecycle_events(self, pipeline_record):
        """cloud_scan_redundant must capture the redundant scan lifecycle events."""
        source_text = load_text(INPUT_FILES["lianke_scan_redundant.log"])
        output = pipeline_record["cloud_scan_redundant"]
        assert output, "cloud_scan_redundant is empty"
        if isinstance(output, str):
            assert len(output.strip().split("\n")) >= 1, (
                "cloud_scan_redundant should contain log content"
            )
        elif isinstance(output, dict):
            has_events = "events" in output or "raw_log" in output
            assert has_events, (
                "cloud_scan_redundant object missing 'events' or 'raw_log'"
            )

    def test_cloud_scans_are_distinct(self, pipeline_record):
        """The primary and redundant scan fields must be distinguishable."""
        primary = pipeline_record["cloud_scan_primary"]
        redundant = pipeline_record["cloud_scan_redundant"]
        # They should not be identical references or identical content
        assert primary is not redundant, (
            "cloud_scan_primary and cloud_scan_redundant are the same object reference"
        )
        # Serialize to compare content
        assert json.dumps(primary, sort_keys=True) != json.dumps(redundant, sort_keys=True), (
            "cloud_scan_primary and cloud_scan_redundant have identical content; they must be distinct"
        )

