class TestTimestampsAndIdentifiersPreserved:
    """Tests that timestamps and identifiers are preserved exactly from source files."""

    def test_community_publication_timestamps_preserved(self, pipeline_record):
        """Timestamps in community_publication must match source exactly."""
        source = load_json(INPUT_FILES["moltbook_publish_confirmation.json"])
        output = pipeline_record["community_publication"]
        # Find timestamp-like keys in source
        timestamp_keys = [k for k in source if "time" in k.lower() or "date" in k.lower() or "at" in k.lower()]
        for key in timestamp_keys:
            assert key in output, f"community_publication missing timestamp key: {key}"
            assert output[key] == source[key], (
                f"community_publication '{key}' value changed: {source[key]} -> {output[key]}"
            )

    def test_watermarked_pdf_identifiers_preserved(self, pipeline_record):
        """Watermark identifier and hash must match source exactly."""
        source = load_json(INPUT_FILES["watermarked_pdf_metadata.json"])
        output = pipeline_record["watermarked_pdf"]
        for key in source:
            assert key in output, f"watermarked_pdf missing key: {key}"
            assert output[key] == source[key], (
                f"watermarked_pdf '{key}' value changed: {source[key]} -> {output[key]}"
            )

    def test_fixture_provenance_identifiers_preserved(self, pipeline_record):
        """fixture_provenance identifiers must match source exactly."""
        source = load_json(INPUT_FILES["fixture_manifest.json"])
        output = pipeline_record["fixture_provenance"]
        # Check top-level scalar fields
        for key in source:
            if key in output and not isinstance(source[key], (list, dict)):
                assert output[key] == source[key], (
                    f"fixture_provenance '{key}' value changed: {source[key]} -> {output[key]}"
                )


class TestInputFilesUnmodified:
    """Tests that input files are not modified by the task."""

    def test_all_input_files_still_exist(self):
        """All 14 input files must still exist and be non-empty after task completion."""
        for name, path in INPUT_FILES.items():
            assert path.exists(), f"Input file {path} no longer exists"
            assert path.is_file(), f"Input path {path} is not a file"
            assert path.stat().st_size > 0, f"Input file {path} is empty"
